# リソース自動展開 (マルチコンバータ組み込み時にのみ利用)
def extract_resource(values: dict, values_ex: dict, pre_converted_dir: Path):

	num_workers = values_ex['num_workers']
	input_dir = Path(values['input_dir'])
	data_dir = Path(input_dir / 'Data')
	voice_dir = Path(input_dir / 'Voice')

	# 動画コピー
	movie_dir = Path(pre_converted_dir / 'movie')
	movie_dir.mkdir(parents=True, exist_ok=True)
	shutil.copyfile(Path(data_dir / 'NATSUOPN.HXP'), Path(movie_dir / 'op.wmv'))

	# 展開対象 (アーカイブパス, 展開先, 画像変換形式)
	arc_list = [
		[Path(data_dir / 'NATSUSCN.HXP'), '_scn', ''],
		[Path(data_dir / 'NATSUCHA.HXP'), '_cha', 'png'],
		[Path(data_dir / 'NATSUSYS.HXP'), '_sys', 'png'],
		[Path(data_dir / 'NATSUFCG.HXP'), '_fcg', 'png'],
		[Path(data_dir / 'NATSUEND.HXP'), '_end', 'png'],
		[Path(data_dir / 'NATSUBGM.HXP'), '_bgm', ''],
		[Path(data_dir / 'NATSUWAV.HXP'), '_se', ''],
	]
	for i in range(1, 25): arc_list.append([Path(voice_dir / f'NATSUV{i:02d}.HXP'), '_voice', ''])

	# arc展開
	with concurrent.futures.ThreadPoolExecutor(max_workers=num_workers) as executor:
		futures = []

		for arc_path, dir_name, img_fmt in arc_list:
			if not arc_path.is_file(): raise FileNotFoundError(f'{arc_path}が見つかりません')#なければ強制エラー
			futures.append(executor.submit(extract_archive, arc_path, dir_name, img_fmt, pre_converted_dir))

		for future in futures: future.result()

	return


# リソース自動展開本処理
def extract_archive(arc_path: Path, dir_name: str, img_fmt: str, pre_converted_dir: Path):
	from utils import extract_archive_garbro # type: ignore

	ex_dir = Path(pre_converted_dir / f'_ex_{arc_path.stem}')
	if img_fmt: extract_archive_garbro(arc_path, ex_dir, img_fmt)
	else: extract_archive_garbro(arc_path, ex_dir)

	result_dir = Path(pre_converted_dir / dir_name)
	result_dir.mkdir(parents=True, exist_ok=True)

	for p in sorted(ex_dir.glob('*')):
		if dir_name in ['_bgm', '_se']:
			# 音声はスクリプト内のIDに合わせて1始まりにする (拡張子なしの空ダミーは除外)
			if not p.suffix: continue
			shutil.move(p, Path(result_dir / f'{int(p.stem) + 1}{p.suffix.lower()}'))
		else:
			shutil.move(p, Path(result_dir / p.name.lower()))

	# 元の展開先ディレクトリ削除
	shutil.rmtree(ex_dir)

	return


# Shift-JIS(+外字)デコード
def sjis_decode(b: bytes):
	gaiji = {b'\x87\x78': '♪', b'\x87\x79': '（汗', b'\x87\x7a': '（汗', b'\x87\x7b': '／／／'}
	out = ''
	i = 0
	while i < len(b):
		c = b[i]
		if (0x81 <= c <= 0x9f) or (0xe0 <= c <= 0xfc):
			pair = b[i:i + 2]
			if pair in gaiji: out += gaiji[pair]
			else: out += pair.decode('cp932')
			i += 2
		else:
			out += bytes([c]).decode('cp932')
			i += 1
	return out


# 半角→全角
def to_zen(s: str):
	out = ''
	for ch in s:
		o = ord(ch)
		if ch == ' ': out += '　'
		elif 0x21 <= o <= 0x7e: out += chr(o + 0xfee0)
		else: out += ch
	return out


# 式デコード(逆ポーランド形式 -> 構文木)
def read_expr(b: bytes, p: int):
	st = []
	cmp_ops = ['==', '!=', '<', '<=', '>', '>=']
	bin_ops = {0: '+', 1: '-', 8: '*', 9: '/', 10: '%', 11: '&', 12: '|', 13: '&&', 14: '||'}
	asg_ops = ['=', '+=', '-=', '*=', '/=', '%=', '&=', '|=']

	while True:
		c = b[p]
		p += 1
		if c == 0xff: break
		hi, lo = c >> 4, c & 15

		if hi == 0:
			if lo < 8: v = lo
			elif lo < 13: v = 7 - lo
			elif lo == 13: v = int.from_bytes(b[p:p + 1], 'big', signed=True); p += 1
			elif lo == 14: v = int.from_bytes(b[p:p + 2], 'big', signed=True); p += 2
			else: v = int.from_bytes(b[p:p + 4], 'big', signed=True); p += 4
			st.append(('n', v))

		elif hi in (1, 2, 3):
			if lo < 14: i = lo
			elif lo == 14: i = b[p]; p += 1
			else: i = int.from_bytes(b[p:p + 2], 'big'); p += 2
			st.append(('v', hi, i))

		elif hi == 4:
			y = st.pop(); x = st.pop()
			st.append(('a', asg_ops[lo], x, y))

		elif hi == 5:
			y = st.pop(); x = st.pop()
			st.append(('b', cmp_ops[lo], x, y))

		elif hi == 6 and lo in bin_ops:
			y = st.pop(); x = st.pop()
			st.append(('b', bin_ops[lo], x, y))

		else:
			raise ValueError(f'未対応の式トークン {c:02x}')

	return st[-1], p


# 文字列引数デコード
def read_str(b: bytes, p: int):
	c = b[p]
	if c >= 0x20:
		q = b.index(b'\x00', p)
		return ('s', b[p:q]), q + 1
	if c == 0: return ('s', b''), p + 1
	raise ValueError('未対応の文字列引数')


# 可変引数リストデコード
def read_args(b: bytes, p: int):
	args = []
	while True:
		t = b[p]
		p += 1
		if t == 0: return args, p
		if t == 1:
			s, p = read_str(b, p)
			args.append(s)
		else:
			e, p = read_expr(b, p)
			args.append(('e', e))


# シナリオバイナリ→命令リスト
def decode_script(b: bytes):
	ops = []
	p = 0x10
	while p < len(b):
		op = b[p]
		d = {'p': p, 'op': op}
		q = p + 1

		if op == 0xff: pass
		elif op == 0x00:
			d['e'], q = read_expr(b, q)
		elif op in (0x01, 0x03):
			d['e'], q = read_expr(b, q)
			d['t'] = int.from_bytes(b[q:q + 3], 'big'); q += 3
		elif op == 0x04:
			d['t'] = int.from_bytes(b[q:q + 3], 'big'); q += 3
		elif op == 0x05:
			d['e'], q = read_expr(b, q)
			n = int.from_bytes(b[q:q + 2], 'big'); q += 2 + 3 * n
		elif op == 0x08:
			d['e'], q = read_expr(b, q)
		elif op == 0x09:
			d['name'], q = read_str(b, q)
			d['i'], q = read_expr(b, q)
			d['flag'], q = read_expr(b, q)
			d['args'], q = read_args(b, q)
		elif op == 0x0a:
			d['cmd'], q = read_expr(b, q)
			d['args'], q = read_args(b, q)
		elif op == 0x15:
			d['e'], q = read_expr(b, q)
		else:
			raise ValueError(f'未対応の命令 {op:02x} (offset {p:x})')

		d['end'] = q
		ops.append(d)
		p = q

	return ops


# ゲーム内変数→ONS変数番号 (200以上はグローバル変数になるため、ゲーム内の変数は200未満に詰める)
def fvar(t: int, i: int):
	if t == 1: return {0: 191, 10: 192}[i]
	if 500 <= i <= 670: return i - 490
	if 313 <= i <= 319: return i - 132
	return {789: 188, 790: 189, 792: 190}[i]


# 構文木→ONSの値表記
def val_str(e):
	if e[0] == 'n': return str(e[1])
	if e[0] == 'v' and e[1] in (1, 3): return f'%{fvar(e[1], e[2])}'
	raise ValueError(f'未対応の値 {e}')


# 構文木→論理式ノード
def cond_node(e):
	zero_vars = [500]# 体験版フラグ(製品版では常に0)
	if e[0] == 'b' and e[1] == '&&': return ('and', [cond_node(e[2]), cond_node(e[3])])
	if e[0] == 'b' and e[1] == '||': return ('or', [cond_node(e[2]), cond_node(e[3])])
	if e[0] == 'b' and e[1] in ['==', '!=', '<', '<=', '>', '>=']:
		x, y = e[2], e[3]
		if x[0] == 'v' and x[1] == 3 and x[2] in zero_vars and y[0] == 'n': x = ('n', 0)
		if x[0] == 'n' and y[0] == 'n':
			return ('const', eval(f'{x[1]}{e[1]}{y[1]}'))
		return ('cmp', val_str(x), e[1], val_str(y))
	if e[0] == 'v':
		if e[1] == 3 and e[2] in zero_vars: return ('const', False)
		return ('cmp', val_str(e), '!=', '0')
	if e[0] == 'n': return ('const', e[1] != 0)
	raise ValueError(f'未対応の条件式 {e}')


# 論理式ノード簡約
def cond_simplify(n):
	if n[0] in ('and', 'or'):
		kids = [cond_simplify(k) for k in n[1]]
		is_and = (n[0] == 'and')
		out = []
		for k in kids:
			if k[0] == 'const':
				if k[1] != is_and: return ('const', not is_and)
				continue
			out.append(k)
		if not out: return ('const', is_and)
		if len(out) == 1: return out[0]
		return (n[0], out)
	return n


# 比較の反転
def cmp_inv(n):
	inv = {'==': '!=', '!=': '==', '<': '>=', '>=': '<', '>': '<=', '<=': '>'}
	return ('cmp', n[1], inv[n[2]], n[3])


# 論理式ノードの否定
def node_not(n):
	if n[0] == 'const': return ('const', not n[1])
	if n[0] == 'cmp': return cmp_inv(n)
	return ('or' if n[0] == 'and' else 'and', [node_not(k) for k in n[1]])


# 条件ジャンプ生成 (jump_true=Trueで真のとき/Falseで偽のときtargetへ飛ぶ)
def cond_lines(n, target: str, jump_true: bool, ctx: dict):
	n = cond_simplify(n)

	def cmp_s(c): return f'{c[1]}{c[2]}{c[3]}'

	if n[0] == 'const':
		return [f'goto {target}'] if n[1] == jump_true else []

	if n[0] == 'cmp':
		return [f'if {cmp_s(n if jump_true else cmp_inv(n))} goto {target}']

	# 「真のときorで飛ぶ」「偽のときandで飛ぶ」は各子要素を順に処理
	if (n[0] == 'or') == jump_true:
		lines = []
		for k in n[1]: lines += cond_lines(k, target, jump_true, ctx)
		return lines

	# 全て単純比較なら1行にまとめる
	if all(k[0] == 'cmp' for k in n[1]):
		cs = [k if jump_true else cmp_inv(k) for k in n[1]]
		return ['if ' + ' & '.join(cmp_s(c) for c in cs) + f' goto {target}']

	# 複雑な場合はスキップラベルで分解
	ctx['skip'] += 1
	skip = f'*sk{ctx["skip"]}'
	lines = []
	for i, k in enumerate(n[1]):
		if i < len(n[1]) - 1:
			lines += cond_lines(k, skip, not jump_true, ctx)
		else:
			lines += cond_lines(k, target, jump_true, ctx)
	lines.append(skip)
	return lines
#<<END_PART1>>


# 構文木内のflag変数(f[N])収集
def collect_reads(e, reads: set):
	if e[0] == 'v' and e[1] == 3: reads.add(e[2])
	elif e[0] in ('b', 'a'):
		collect_reads(e[2], reads)
		collect_reads(e[3], reads)
	return


# 引数列→値リスト (定数のみ対応)
def arg_values(args: list):
	out = []
	for a in args:
		if a[0] == 's': out.append(sjis_decode(a[1]))
		elif a[1][0] == 'n': out.append(a[1][1])
		else: raise ValueError(f'未対応の引数 {a}')
	return out


# シナリオ事前走査(使用flag/立ち絵の収集)
def scan_script(ops: list, ctx: dict):
	for d in ops:
		if d['op'] in (0x01, 0x03): collect_reads(d['e'], ctx['reads'])
		if d['op'] == 0x0a and d['cmd'] == ('n', 54):
			v = arg_values(d['args'])
			if v[0] == 2: ctx['chars'].setdefault((v[1].lower(), v[2].lower()), None)
		if d['op'] == 0x0a and d['cmd'] == ('n', 52) and d['args'][0][1][1] == 1:
			collect_reads(d['args'][2][1], ctx['reads'])
	return


# 効果ID取得 (ミリ秒→effect番号)
def eff_id(ms: int, ctx: dict):
	if ms <= 0: ms = 500
	if ms not in ctx['eff']: ctx['eff'][ms] = 20 + len(ctx['eff'])
	return ctx['eff'][ms]


# テキスト整形 (名前, 本文)
def msg_text(raw: str):
	if '\\n' in raw: name, body = raw.split('\\n', 1)
	else: name, body = '', raw
	body = re.sub(r'\$\d+([^:$]*):[^$]*\$', r'\1', body)
	return to_zen(name), to_zen(body)


# シナリオ1本→ONSスクリプト
def scn_cnv(name: str, ops: list, ctx: dict):
	lines = [f'*s{name}']
	# 回想モード用の既読フラグ(グローバル変数)
	for i, r in enumerate(replay_list()):
		if r[0] == name: lines.append(f'mov %{200 + i},1')
	# 引数付き開始用の前置き(op03+op05)がある場合は飛ばす
	start = ops[0]['t'] if (ops[0]['op'] == 0x03 and ops[1]['op'] == 0x05) else ops[0]['p']
	body_ops = [d for d in ops if d['p'] >= start]
	targets = set(d['t'] for d in body_ops if d['op'] in (0x01, 0x03, 0x04))

	def lab(t): return f'*s{name}_{t:x}'

	alive = True
	cur_eff = 0
	choice = []

	for d in body_ops:
		p, op = d['p'], d['op']

		if p in targets:
			lines.append(lab(p))
			alive = True
			cur_eff = 0
		if not alive: continue

		if op == 0x00:
			e = d['e']
			if e[0] != 'a' or e[2][0] != 'v' or e[2][1] != 3: raise ValueError(f'未対応の代入 {e}')
			if e[2][2] in ctx['reads']:
				cmd = {'=': 'mov', '+=': 'add', '-=': 'sub'}[e[1]]
				lines.append(f'{cmd} %{fvar(3, e[2][2])},{val_str(e[3])}')

		elif op in (0x01, 0x03):
			lines += cond_lines(cond_node(d['e']), lab(d['t']), op == 0x01, ctx)

		elif op == 0x04:
			lines.append(f'goto {lab(d["t"])}')
			alive = False

		elif op in (0x08, 0xff):
			lines.append('return')
			alive = False

		elif op == 0x09:
			v = arg_values([('e', d['i']), ('e', d['flag'])] + d['args'])
			if v[0] == 3: lines.append('reset')
			elif v[0] == 16 and v[1] == 1: lines.append(f'ed {v[2]}')

		elif op == 0x15:
			lines.append(f'mov %{fvar(1, 10)},600')

		elif op == 0x0a:
			cmd = d['cmd'][1]
			v = arg_values(d['args']) if cmd not in (51, 52) else None

			# メッセージ
			if cmd == 51:
				idx, mid = arg_values(d['args'][:2])
				voice = sjis_decode(d['args'][2][1]).lower()
				nm, tx = msg_text(sjis_decode(d['args'][3][1]))
				if voice: lines.append(f'n "{nm}","{voice}"')
				elif nm: lines.append(f'm "{nm}"')
				lines.append(f'{tx}\\')

			# 選択肢 (有効条件付きの選択肢は、条件の組み合わせごとにselectを用意)
			elif cmd == 52:
				sub = d['args'][0][1][1]
				if sub == 0: choice = []
				elif sub == 1:
					cond = cond_node(d['args'][2][1])
					choice.append([to_zen(sjis_decode(d['args'][1][1])), cond_simplify(cond)])
				elif sub == 2:
					ctx['sel'] += 1
					base = f'*sel{ctx["sel"]}'
					cidx = [i for i, c in enumerate(choice) if c[1] != ('const', True)]
					for mask in range(2 ** len(cidx) - 1):
						node = ('and', [c[1] if (mask >> j) & 1 else node_not(c[1]) for j, c in enumerate([choice[i] for i in cidx])])
						lines += cond_lines(node, f'{base}_v{mask}', True, ctx)
					if cidx: lines.append(f'goto {base}_v{2 ** len(cidx) - 1}')
					for mask in range(2 ** len(cidx)):
						use = [i for i, c in enumerate(choice) if i not in cidx or (mask >> cidx.index(i)) & 1]
						lines.append(f'{base}_v{mask}')
						lines.append('select ' + ','.join(f'"{choice[i][0]}",{base}_{i + 1}' for i in use))
					for i in range(1, len(choice) + 1):
						lines.append(f'{base}_{i}')
						lines.append(f'mov %{fvar(1, 0)},{i}' + (f':goto {base}_e' if i < len(choice) else ''))
					lines.append(f'{base}_e')

			# システム
			elif cmd == 50:
				if v[0] == 12: lines.append('bgmstop:dwavestop -1:skipoff:mpegplay "movie\\op.wmv",1')

			# 画面/音声制御
			elif cmd == 54:
				s = v[0]
				if s == 1:
					lines.append(f'b "{v[1].lower()}"')
				elif s == 2:
					info = ctx['chars'][(v[1].lower(), v[2].lower())]
					idx, x, y = info if info else (0, 0, 0)
					lines.append(f'lsp {20 + v[3]},"c\\{idx}.png",{v[3] * 200 + x},{y}')
				elif s == 4:
					cur_eff = v[2] * 10 if len(v) > 2 else 500
				elif s == 16:
					cur_eff = v[1] * 10
				elif s == 5:
					lines.append(f'p {eff_id(cur_eff, ctx)}')
					cur_eff = 0
				elif s == 6:
					lines.append('bgmstop' if v[1] == 0 else f'bgm "bgm\\{v[1]}.ogg"')
				elif s == 7:
					lines.append(f'dwave {v[2]},"se\\{v[1]}.ogg"')
				elif s == 8:
					lines.append(f'dwaveloop {v[2]},"se\\{v[1]}.ogg"')
				elif s == 9:
					lines.append(f'gosub *s{v[1].lower()}')
				elif s == 11:
					lines.append('dwavestop 1:dwavestop 2:dwavestop 3:dwavestop 4' if v[1] == 0 else f'dwavestop {v[1]}')
				elif s == 19:
					lines.append('sx')
				elif s == 23:
					m = v[1] // 100
					card = (v[1] - 327) if m == 7 else ((v[1] - 396) if m == 8 else 436)
					ctx['cal'].update([340 + m - 7, card])
					lines.append(f'dc "{340 + m - 7}","{card}"')
				elif s == 25:
					lines.append(f'fl "{v[1].lower()}"')
				elif s == 26:
					a, b, c, d2 = fvar(3, 313), fvar(3, 314), fvar(3, 789), fvar(3, 790)
					e2 = fvar(3, 792)
					# 0=現在のH-Custom設定を控える / 1=控えた設定へ戻す (シーン中の設定変更は次のシーンから反映)
					if v[1] != 0: lines.append(f'mov %{e2},0:mov %{b},%{c}:mov %{a},%{d2}')
					else: lines.append(f'if %{e2}!=0 mov %{b},%{c}:mov %{a},%{d2}\nmov %{e2},1:mov %{c},%{b}:mov %{d2},%{a}')
				elif s in (10, 15, 20, 21, 24, 28): pass
				else: raise ValueError(f'未対応のサブコマンド {s} ({name} offset {p:x})')

			else: raise ValueError(f'未対応のコマンド {cmd} ({name} offset {p:x})')

	return lines
#<<END_PART2>>


# 立ち絵合成(胴体+表情) / ThreadPoolExecutor用
def chara_compose(i: int, key: tuple, cha_dir: Path, out_dir: Path):
	body = Image.open(Path(cha_dir / f'{key[0]}.png')).convert('RGBA')
	face = Image.open(Path(cha_dir / f'{key[1]}.png')).convert('RGBA')

	w = max(body.size[0], face.size[0])
	h = max(body.size[1], face.size[1])
	canvas = Image.new('RGBA', (w, h), (0, 0, 0, 0))
	canvas.alpha_composite(body, (0, h - body.size[1]))
	canvas.alpha_composite(face, (0, h - face.size[1]))

	# 透明部分を切り詰めて容量削減 (画面下端に合わせて配置する)
	box = canvas.getchannel('A').getbbox()
	canvas.crop(box).save(Path(out_dir / f'{i}.png'))

	return key, (i, box[0], 600 - h + box[1])


# 立ち絵一括合成
def chara_images(pre_converted_dir: Path, ctx: dict, num_workers: int):
	cha_dir = Path(pre_converted_dir / '_cha')
	out_dir = Path(pre_converted_dir / 'c')
	out_dir.mkdir(parents=True, exist_ok=True)

	with concurrent.futures.ThreadPoolExecutor(max_workers=num_workers) as executor:
		futures = [executor.submit(chara_compose, i, key, cha_dir, out_dir) for i, key in enumerate(sorted(ctx['chars']))]
		for future in futures:
			key, info = future.result()
			ctx['chars'][key] = info

	return


# ボタン画像のラベル消去 (左端と右端の色を行ごとに補間して塗りつぶす)
def erase_label(img: Image.Image):
	pix = img.load()
	xl, xr = 62, 203
	for y in range(10, 46):
		cl = [sum(pix[x, y][c] for x in range(xl, xl + 3)) / 3 for c in range(3)]
		cr = [sum(pix[x, y][c] for x in range(xr, xr + 2)) / 2 for c in range(3)]
		for x in range(xl + 3, xr):
			t = (x - xl) / (xr - xl)
			pix[x, y] = tuple(int(cl[c] * (1 - t) + cr[c] * t) for c in range(3))
	return img


# ボタン画像にラベルを描く (元画像に近い明朝系・字間広めの白文字)
def draw_label(img: Image.Image, text: str):
	font = ImageFont.load_default(21)
	for name in ['times.ttf', 'Times New Roman.ttf', 'DejaVuSerif.ttf']:
		try:
			font = ImageFont.truetype(name, 21)
			break
		except OSError: pass

	dr = ImageDraw.Draw(img)
	spacing = 8
	widths = [dr.textlength(c, font=font) for c in text]
	x = 198 - (sum(widths) + spacing * (len(text) - 1))
	for c, w in zip(text, widths):
		dr.text((x, 38), c, font=font, fill=(255, 255, 255), anchor='ls')
		x += w + spacing

	return img


# UI画像作成
def ui_images(pre_converted_dir: Path, ctx: dict):
	sys_dir = Path(pre_converted_dir / '_sys')

	# 起動時の注意事項/ロゴ
	Image.open(Path(sys_dir / '00109.png')).convert('RGB').save(Path(pre_converted_dir / 'notice.png'))
	Image.open(Path(sys_dir / '00110.png')).convert('RGB').save(Path(pre_converted_dir / 'logo.png'))

	# ロゴ表示時の音声(ランダムで1つ再生)
	lse_dir = Path(pre_converted_dir / 'lse')
	lse_dir.mkdir(parents=True, exist_ok=True)
	for n in range(284, 289): shutil.copyfile(Path(sys_dir / f'{n:05d}.ogg'), Path(lse_dir / f'{n}.ogg'))

	# タイトル背景 (AlbumModeボタンをConfigに描き換え)
	title = Image.open(Path(sys_dir / '00111.png')).convert('RGB')
	title.paste(draw_label(erase_label(title.crop((27, 411, 27 + 208, 411 + 49))), 'Config'), (27, 411))
	title.save(Path(pre_converted_dir / 'title.png'))

	# タイトルボタン(マウスオーバー時の画像を縦に並べる)
	sheet = Image.new('RGBA', (208, 49 * 5))
	for i in range(5):
		btn = Image.open(Path(sys_dir / f'{289 + i:05d}.png')).convert('RGB').crop((0, 49, 208, 98))
		if i == 2: btn = draw_label(erase_label(btn), 'Config')
		sheet.paste(btn.convert('RGBA'), (0, 49 * i))
	sheet.save(Path(pre_converted_dir / 'tbtn.png'))

	# メッセージウィンドウ(半透明の背景を足し、右と下に透明余白を追加)
	win = Image.open(Path(sys_dir / '00000.png')).convert('RGBA')
	base = Image.new('RGBA', win.size, (0, 0, 0, 0))
	ImageDraw.Draw(base).rectangle((2, 31, win.size[0] - 3, win.size[1] - 3), fill=(67, 38, 38, 170))
	base.alpha_composite(win)
	pad = Image.new('RGBA', (win.size[0] * 3 // 2, win.size[1] * 3 // 2), (0, 0, 0, 0))
	pad.paste(base, (0, 0))
	pad.save(Path(pre_converted_dir / 'win.png'))

	# 名前欄 (背景のメッセージウィンドウに馴染むよう、描画後にPILで輝度を下げる)
	tab = Image.new('RGBA', (214, 34), (0, 0, 0, 0))
	dr = ImageDraw.Draw(tab)
	dr.polygon([(2, 33), (8, 6), (14, 3), (188, 3), (200, 18), (212, 33)], fill=(226, 232, 218, 255))
	dr.rectangle((2, 30, 212, 33), fill=(171, 178, 163, 255))
	tab_rgb = ImageEnhance.Brightness(tab.convert('RGB')).enhance(0.75)
	tab_rgb.putalpha(tab.getchannel('A'))
	tab_rgb.save(Path(pre_converted_dir / 'tab.png'))

	# コンフィグ/回想モード/ロード画面の背景 (文字を読みやすくするため、コンフィグと回想は輝度を下げる)
	for src_name, dst_name in [['00294', 'cfgbg'], ['00470', 'rpbg']]:
		ImageEnhance.Brightness(Image.open(Path(sys_dir / f'{src_name}.png')).convert('RGB')).enhance(0.45).save(Path(pre_converted_dir / f'{dst_name}.png'))
	load = Image.open(Path(sys_dir / '00157.png')).convert('RGBA')
	black = Image.new('RGBA', load.size, (0, 0, 0, 255))
	black.alpha_composite(load)
	black.convert('RGB').save(Path(pre_converted_dir / 'load.png'))

	# 日付カード用画像
	cal_dir = Path(pre_converted_dir / 'cal')
	cal_dir.mkdir(parents=True, exist_ok=True)
	for i in ctx['cal']:
		Image.open(Path(sys_dir / f'{i:05d}.png')).convert('RGB').save(Path(cal_dir / f'{i}.png'))

	return


