# エンディング(スタッフロール) / end_dir: NATSUENDの画像
def ed_txt(end_dir: Path):
	# 原作の表示順 (ロゴ→STAFF→各担当→THANK YOU→AcaciaSoft)
	order = list(range(20))

	txt = '*ed\n\tgetparam %0\n\tbgmstop:dwavestop -1:skipoff\n'
	for i, h in enumerate(['kika', 'tugu', 'rann', 'akki', 'mika']): txt += f'\tif %0=={i} mov $0,"{h}"\n'
	txt += '\tcsp -1\n\tlsp 100,"bg\\"+$0+"_end.png",0,0\n\tprint 10\n\tbgm "bgm\\15.ogg"\n\twait 9000\n'
	txt += '\tlsp 100,"bg\\black.png",0,0\n\tprint 12\n'
	for n in order:
		w, h = Image.open(Path(end_dir / f'{n:05d}.png')).size
		txt += f'\tlsp 5,"end\\{n:05d}.png",{(800 - w) // 2},{(600 - h) // 2}\n\tprint 12\n\twait 3600\n\tcsp 5\n\tprint 12\n'
	txt += '\tbgmstop\n\tcsp -1\n\treset\nreturn\n'
	return txt
