# メイン処理関数 ※pre_converted_dir→今までのコンバータのsame_hierarchy
def main(values: dict = {}, values_ex: dict = {}, pre_converted_dir: Path = Path.cwd()):

	# マルチコンバータ利用時自動展開
	if values: extract_resource(values, values_ex, pre_converted_dir)
	num_workers = values_ex['num_workers'] if values_ex else 4

	# 変換中に使う情報 (reads: 条件で参照されるflag)
	ctx = {'skip': 0, 'sel': 0, 'reads': set([313, 314, 319, 789, 790, 792]), 'chars': {}, 'eff': {}, 'cal': set()}

	# シナリオ事前走査
	scripts = []
	for p in sorted(Path(pre_converted_dir / '_scn').glob('*')):
		ops = decode_script(p.read_bytes())
		scan_script(ops, ctx)
		scripts.append([p.name, ops])

	# 画像処理
	chara_images(pre_converted_dir, ctx, num_workers)

	# シナリオ変換
	txt = ''
	for name, ops in scripts:
		txt += '\n'.join(scn_cnv(name, ops, ctx)) + '\n'

	# UI画像(日付カードなどシナリオ変換後に判明するものを含む)
	ui_images(pre_converted_dir, ctx)

	# エフェクト定義用の命令文
	add0txt_effect = ''
	for ms, i in ctx['eff'].items(): add0txt_effect += f'effect {i},10,{ms}\n'

	# default.txtを(今さら)読み込み
	txt = default_txt(add0txt_effect, ed_txt(Path(pre_converted_dir / '_end')), replay_txt()) + txt

	# 0.txt書込み
	with open(Path(pre_converted_dir / '0.txt'), 'w', encoding='cp932') as f: f.write(txt)

	# 素材整理 / 不要ファイル削除
	for src, dst in [['_fcg', 'bg'], ['_bgm', 'bgm'], ['_se', 'se'], ['_voice', 'voice'], ['_end', 'end']]:
		shutil.move(Path(pre_converted_dir / src), Path(pre_converted_dir / dst))
	for dir_name in ['_scn', '_cha', '_sys']: shutil.rmtree(Path(pre_converted_dir / dir_name))

	# 終了
	return


# 単体動作 (事前にリソース手動展開必須)
if __name__ == "__main__":
	main()



